const execution = $json.execution;
const workflow = $json.workflow;
const error = execution.error || {};

const correlationId = 'ERR-' + Date.now().toString(36).toUpperCase();
const timestamp = new Date().toISOString();

const alertMessage = '🚨 *ALERTA DE FALHA CRÍTICA — VN AI ECOSYSTEM*\n\n' +
  '🆔 *Correlation ID:* `' + correlationId + '`\n' +
  '⚙️ *Workflow:* `' + workflow.name + '` (ID: ' + workflow.id + ')\n' +
  '⏱️ *Timestamp:* `' + timestamp + '`\n' +
  '❌ *Erro:* ' + (error.message || 'Erro não especificado') + '\n\n' +
  '🔍 *Localização:* Nó `' + (error.node ? error.node.name : 'Desconhecido') + '`\n' +
  '🛠️ *Ação:* Automação isolada. Nenhuma alteração destrutiva realizada.';

return [{
  json: {
    correlationId,
    timestamp,
    workflowId: workflow.id,
    workflowName: workflow.name,
    errorMessage: error.message,
    alertMessage
  }
}];
